//***********************************************************************************************************
// Here are two articles to help you get started with KQL:
// KQL reference guide - https://aka.ms/KQLguide
// SQL - KQL conversions - https://aka.ms/sqlcheatsheet
//***********************************************************************************************************

// Use "take" to view a sample number of records in the table and check the data.
RapidDelivery
| take 100

// See how many records are in the table.
RapidDelivery
| count

// This query returns the number of ingestions per hour in the given table.
YOUR_TABLE_HERE
| summarize IngestionCount = count() by bin(ingestion_time(), 1h)

// Return specified columns
RapidDelivery
| take 5
| project CustomerKey, OrderDate, ProductKey, UnitPrice, OrderQuantity

RapidDelivery | getschema

RapidDelivery
| take 5
| project-away ShipDate

// Combine Standard Delivery and Rapid Delivery with a union operation, return 100 rows and limit columns returned
RapidDelivery
| union StandardDelivery 
| take 100
| project SalesOrderNumber, OrderDate, ProductKey, OrderQuantity, UnitPrice

// Add a filter to limit the final result set
// Return only rows where ProductKey = 147
RapidDelivery
| where ProductKey == 147

// Return only products from a list using IN
RapidDelivery
| where ProductKey in(22, 31, 147)

// Rename SalesOrderNumber to OrderNumber
RapidDelivery
| where ProductKey in(22, 31, 147)
| project-rename OrderNumber = SalesOrderNumber

// Count the number of transactions for products (22, 31, 147)
RapidDelivery
| where ProductKey in(22, 31, 147)
| project-rename OrderNumber = SalesOrderNumber
| count

// Return distinct count of products
RapidDelivery
| summarize distinctProductKeys = dcount(ProductKey)

// Performing Basic Aggregations
RapidDelivery
| summarize TotalSales = sum(UnitPrice * OrderQuantity)

// Summarize TotalSales and TransactionTotal
// Group by ProductKey
// Order by TotalSales Descending
RapidDelivery
| summarize 
        TotalSales = sum(UnitPrice * OrderQuantity), 
        TransactionTotal = count() 
    by ProductKey
| order by TotalSales desc
